"""Bit-exactness golden for `navalai.resistance`, and the speed it bought.

WHY THIS FILE EXISTS. `resistance.michell_rw` was the largest single item left
in `evaluate()` (~50% of what remained after the geometry kernel was
optimised), and the whole of that cost sat in `_free_wave_vals`: a Python loop
over 220 theta nodes making three `np.trapezoid` calls each, i.e. 660 wrapper
invocations at ~62 us of overhead apiece. The loop was replaced by a chunked,
axis-batched form. Nothing about the PHYSICS moved: not a constant, not the
theta-grid density, not the quadrature resolution, not a tolerance.

"Nothing moved" is not a claim to be asserted, it is a claim to be MEASURED, so
this file pins the module's numbers BIT FOR BIT — `float.hex()` on every scalar
and a SHA-256 over the exact IEEE-754 bytes of every array. Not `repr`, not
`allclose`, not 1e-15: the Michell number feeds pinned figures all over this
repository (`tests/test_phase1.py`, `tests/test_multihull.py`,
`tests/test_gapfix_physics.py`, the surrogate's training targets), so a
one-ulp drift is a real change wearing a rounding error's clothes.

THE THREE FLOAT TRAPS THAT ACTUALLY BIT, recorded because they are not folklore
and the next person to touch this loop will meet them again (all MEASURED on
this machine, numpy 2.3.5 / CPython 3.12 / glibc):

  1. `np.float64(x) ** 2` is NOT `np.square(x)` and is NOT `x * x`.
     The numpy SCALAR path goes to libm `pow`, which is <1 ulp but not
     correctly rounded; the ARRAY path `arr ** 2` is rewritten by numpy's
     `fast_scalar_power` into `square`, which IS the correctly-rounded
     product. MEASURED: they disagree on **388 of 400 000** uniform doubles in
     [0.5, 5000). Worked example —
         x            = 0x1.32d240c44716bp+10
         np.float64(x) ** 2 = 0x1.6fbb4f838c599p+20   (libm pow)
         x * x              = 0x1.6fbb4f838c59ap+20   (exact product)
     The loop this file replaced computed `sc ** 2` and `re ** 2 + im ** 2` on
     numpy SCALARS. The batched form therefore uses `np.float_power(a, 2.0)`,
     which is the only array expression tested here that reproduces the scalar
     path exactly (`arr ** 2`, `arr ** 2.0`, `np.square`, `arr * arr`,
     `np.power(arr, 2)` and `np.power(arr, 2.0)` ALL fail). See
     `test_numpy_scalar_square_is_libm_pow_not_the_product`.
  2. `** 3` is the opposite case: numpy has no fast path for exponent 3, so
     BOTH the scalar and the array route go to libm `pow` and agree exactly.
     The distinction is worth stating because "use float_power everywhere" and
     "use ** everywhere" are each wrong half the time.
  3. Summation ORDER. `np.trapezoid` finishes with `.sum(axis)`, which is
     pairwise, so the answer depends on the reduction length and layout.
     MEASURED here (`test_numpy_trapezoid_batches_bit_exactly`): promoting the
     reduction to a new leading axis is bit-exact — a 1-D reduction equals row
     `i` of the same reduction done 2-D over `axis=-1`, a 2-D `axis=1`
     reduction equals a 3-D `axis=2` one, and chunking the leading axis
     changes nothing. That is WHY the batch is allowed at all; had it failed,
     the trapezoid rule would have had to be written out by hand in the loop's
     own accumulation order, or the loop kept.

WHAT WAS REFUSED. `fx[i] = sum_j w_j dydx[i,j]` is a matrix-vector product and
BLAS would do it in a fraction of the time — and in its own accumulation order,
which is not this one. Not taken. Likewise the theta grid, the 241x44 offsets
grid and `N_THETA_PER_HULL_LENGTH_OF_SEPARATION` are all quadrature resolutions
with measured convergence tables above them in `resistance.py`; cheapening any
of them would have been a physics change sold as a speedup.

REGENERATING THE GOLDEN. `python -m tests.test_resistance --write` rewrites the
literal below from the CURRENT module. That is a deliberate act with an
obligation attached: the diff must be empty unless you can say which number
moved and why. A golden regenerated to make a red test green is worse than no
golden.
"""

from __future__ import annotations

import hashlib
import math

import numpy as np
import pytest

from navalai import grammar
from navalai import resistance as R
from navalai.geometry import Hull


# ---------------------------------------------------------------------------
# EXACT SERIALISATION
# ---------------------------------------------------------------------------

def _h(v) -> str:
    """A float as its EXACT bit pattern. `repr` round-trips; `hex` IS the bits."""
    f = float(v)
    if math.isnan(f):
        return "nan"
    if math.isinf(f):
        return "inf" if f > 0 else "-inf"
    return f.hex()


def _put(out: dict, key: str, v) -> None:
    """Record one value under `key`, exactly, whatever kind of value it is."""
    if isinstance(v, (bool, np.bool_)):
        out[key] = "bool:%d" % int(v)
    elif isinstance(v, (int, np.integer)) and not isinstance(v, bool):
        out[key] = "int:%d" % int(v)
    elif isinstance(v, str):
        out[key] = "str:" + v
    elif v is None:
        out[key] = "none"
    elif isinstance(v, (float, np.floating)):
        out[key] = _h(v)
    elif isinstance(v, np.ndarray):
        a = np.ascontiguousarray(v, dtype=np.float64)
        flat = a.ravel()
        out[key + ".n"] = "int:%d" % flat.size
        # The digest is over the exact IEEE-754 bytes, so it is as strict as
        # element-by-element hex and does not put 17 600 hexes in a literal.
        out[key + ".sha256"] = "sha:" + hashlib.sha256(flat.tobytes()).hexdigest()
        if flat.size:
            # Three readable anchors so a mismatch report says something.
            out[key + ".first"] = _h(flat[0])
            out[key + ".mid"] = _h(flat[flat.size // 2])
            out[key + ".last"] = _h(flat[-1])
    elif isinstance(v, (tuple, list)):
        out[key + ".len"] = "int:%d" % len(v)
        for i, item in enumerate(v):
            _put(out, "%s[%d]" % (key, i), item)
    elif isinstance(v, dict):
        for k in sorted(v):
            _put(out, "%s.%s" % (key, k), v[k])
    else:
        raise TypeError("golden cannot serialise %r (%s)" % (v, type(v)))


def _raises(out: dict, key: str, fn, *a, **k) -> None:
    """Record a REFUSAL exactly — the message is part of the contract."""
    try:
        fn(*a, **k)
    except Exception as exc:                       # noqa: BLE001 - by design
        _put(out, key, "%s: %s" % (type(exc).__name__, exc))
    else:
        _put(out, key, "NO-RAISE")


# ---------------------------------------------------------------------------
# THE FIXTURES THE GOLDEN RUNS ON
# ---------------------------------------------------------------------------
#
# TWO FAMILIES ON PURPOSE. The `wig_*` grids are analytic and depend on NOTHING
# outside this file, so they pin `michell_rw` even if the geometry kernel moves
# underneath. The `ref_*` grids are real `Hull` offsets at roundness 0 / 0.65 /
# 1.0 — the hard-chine, mid and full-fillet corners of the bilge gene — which
# is the coverage that matters for the production path and which does couple to
# `geometry.py` by construction (it is the production path's own input).

def _wigley_grid(nx: int, nz: int, lwl: float = 10.0, beam: float = 1.0,
                 draft: float = 0.6):
    """A Wigley demihull half-breadth grid. Analytic, geometry-kernel-free."""
    xs = np.linspace(0.0, lwl, nx)
    zs = np.linspace(-draft, 0.0, nz)
    xi = 2.0 * (xs - 0.5 * lwl) / lwl
    Y = 0.5 * beam * (1.0 - xi[:, None] ** 2) * (1.0 - (zs[None, :] / draft) ** 2)
    return xs, zs, Y


def _reference_hulls():
    """The reference hull at the three bilge-roundness corners."""
    from navalai.reference import reference_params
    base = np.asarray(reference_params(), dtype=float)
    j = grammar.NAMES.index("roundness")
    out = []
    for r in (0.0, 0.65, 1.0):
        p = base.copy()
        p[j] = float(r)
        out.append(("ref_r%03d" % round(r * 100), p))
    return out


def _grids():
    """(name, xs, zs, Y, lwl) — every centreplane the golden integrates."""
    ns, nz = R.PRODUCTION_GRID["n_stations"], R.PRODUCTION_GRID["nz"]
    out = [("wig_prod", *_wigley_grid(ns, nz)),
           ("wig_coarse", *_wigley_grid(41, 14)),
           ("wig_odd", *_wigley_grid(97, 25, lwl=6.5, beam=0.7, draft=0.35))]
    grids = [(n, xs, zs, Y, float(xs[-1] - xs[0])) for n, xs, zs, Y in out]
    for name, params in _reference_hulls():
        hull = Hull(params, n_stations=ns)
        xs, zs, Y = hull.offsets_grid(nz=nz, wl=0.0)
        grids.append((name, xs, zs, Y, float(xs[-1] - xs[0])))
    return grids


# Froude numbers: two well inside Michell's envelope, one AT the edge
# (`FN_MICHELL_MAX`), one just outside it, and one below the speed floor.
_FN_CASES = (0.12, 0.28, 0.38, R.FN_MICHELL_MAX, 0.52)
_SEP_RATIOS = (0.25, 0.55, 1.30)      # s / Lwl — below, near and above 1
_RHOS = (1000.0, 1025.0, 1012.5)


# ---------------------------------------------------------------------------
# THE PAYLOAD
# ---------------------------------------------------------------------------

def golden_payload() -> dict:
    """Every number `navalai.resistance` produces, keyed and exact."""
    out: dict = {}

    # -- module constants ---------------------------------------------------
    for name in ("FN_MICHELL_MAX", "RE_TRANSITION_ONSET", "RE_FULLY_TURBULENT",
                 "N_THETA_MONOHULL", "N_THETA_PER_HULL_LENGTH_OF_SEPARATION",
                 "CATAMARAN_INTERFERENCE_AT_INFINITY",
                 "CATAMARAN_THETA_QUADRATURE_ERROR",
                 "CATAMARAN_ASYMPTOTIC_RESIDUAL", "GRID_CONVERGED_TO",
                 "FORM_FACTOR_SIGMA_DECLARED", "NU_WATER"):
        _put(out, "const." + name, getattr(R, name))
    _put(out, "const.FORM_FACTOR_BAND", R.FORM_FACTOR_BAND)
    _put(out, "const.WATANABE_L_OVER_B_BAND", R.WATANABE_L_OVER_B_BAND)
    _put(out, "const.PRODUCTION_GRID", R.PRODUCTION_GRID)
    _put(out, "const.CONVERGED_GRID", R.CONVERGED_GRID)

    # -- nu_water -----------------------------------------------------------
    for rho in (900.0, 1000.0, 1005.0, 1012.5, 1025.0, 1026.0, 1200.0):
        _put(out, "nu_water[%g]" % rho, R.nu_water(rho))

    # -- flow_regime: both halves of the envelope, both sides of each bar ----
    for u, ell in ((0.5, 1.0), (1.0, 1.0), (1.5, 1.0), (3.0, 1.0),
                   (2.5, 10.0), (4.4565, 10.0), (5.2, 10.0), (6.0, 12.0),
                   (0.0, 10.0)):
        for rho in (1000.0, 1025.0):
            fr = R.flow_regime(u, ell, rho)
            k = "flow_regime[%g,%g,%g]" % (u, ell, rho)
            _put(out, k + ".fn", fr.fn)
            _put(out, k + ".re", fr.re)
            _put(out, k + ".michell_ok", fr.michell_ok)
            _put(out, k + ".ittc57_ok", fr.ittc57_ok)
            _put(out, k + ".valid", fr.valid)
            _put(out, k + ".envelope", fr.envelope)
    _raises(out, "flow_regime.zero_length", R.flow_regime, 2.0, 0.0)

    # -- ittc57_cf ----------------------------------------------------------
    for u in (0.01, 1.0, 2.5, 4.4565, 12.0):
        for ell in (1.0, 6.5, 10.0):
            for rho in _RHOS:
                _put(out, "ittc57_cf[%g,%g,%g]" % (u, ell, rho),
                     R.ittc57_cf(u, ell, rho=rho))
    _put(out, "ittc57_cf.explicit_nu", R.ittc57_cf(2.5, 10.0, nu=1.2e-6))

    # -- form_factor: inside the band, off both clamps, outside Watanabe -----
    for cb, ell, b, t in ((0.55, 10.0, 3.2, 0.55), (0.45, 12.0, 1.7, 0.60),
                          (0.70, 6.0, 3.0, 0.30), (0.38, 20.0, 2.5, 0.90),
                          (0.85, 5.0, 2.4, 0.20), (0.60, 7.0, 1.0, 1.0)):
        ff = R.form_factor(cb, ell, b, t)
        k = "form_factor[%g,%g,%g,%g]" % (cb, ell, b, t)
        _put(out, k + ".k", ff.k)
        _put(out, k + ".k_raw", ff.k_raw)
        _put(out, k + ".clamped", ff.clamped)
        _put(out, k + ".sigma_k", ff.sigma_k)
        _put(out, k + ".in_support", ff.in_support)
        _put(out, k + ".violations", ff.envelope_violations)
    for bad in (("cb", 0.0), ("lwl", -1.0), ("beam", float("nan")),
                ("t", 0.0)):
        args = {"cb": 0.55, "lwl": 10.0, "beam": 3.2, "t": 0.55}
        args[bad[0]] = bad[1]
        _raises(out, "form_factor.bad_%s" % bad[0], R.form_factor, **args)

    # -- bow_wave_rise / wet_deck_clearance_g -------------------------------
    for u in (0.0, 1.0, 2.5, 4.4565, 12.0):
        _put(out, "bow_wave_rise[%g]" % u, R.bow_wave_rise(u))
        for c in (0.0, 0.45, 1.2):
            _put(out, "wet_deck_clearance_g[%g,%g]" % (c, u),
                 R.wet_deck_clearance_g(c, u))
    _raises(out, "bow_wave_rise.negative", R.bow_wave_rise, -1.0)
    _raises(out, "bow_wave_rise.nan", R.bow_wave_rise, float("nan"))
    _raises(out, "wet_deck_clearance_g.nan", R.wet_deck_clearance_g,
            float("nan"), 2.0)

    # -- _theta_grid --------------------------------------------------------
    for n in (7, 220, 441, 880, 1760):
        th, sec = R._theta_grid(n)
        _put(out, "theta_grid[%d].thetas" % n, th)
        _put(out, "theta_grid[%d].sec" % n, sec)

    # -- n_theta_for_separation --------------------------------------------
    for ell in (6.5, 10.0):
        for s in (0.5, 2.5, 10.0, 33.0):
            _put(out, "n_theta_for_separation[%g,%g]" % (ell, s),
                 R.n_theta_for_separation(ell, s))

    # -- catamaran_interference --------------------------------------------
    for n in (220, 880):
        th, _ = R._theta_grid(n)
        for k0 in (9.81 / 1.5 ** 2, 9.81 / 4.4565 ** 2):
            for s in (2.5, 13.0):
                _put(out, "catamaran_interference[%d,%.6f,%g]" % (n, k0, s),
                     R.catamaran_interference(k0, th, s))

    # -- the integrand, the integral, the spectrum, the sweep ---------------
    for name, xs, zs, Y, lwl in _grids():
        for fn in _FN_CASES:
            u = fn * math.sqrt(R.G * lwl)
            tag = "%s@fn%.3f" % (name, fn)

            th, sec = R._theta_grid(R.N_THETA_MONOHULL)
            _put(out, "free_wave_vals[%s]" % tag,
                 R._free_wave_vals(xs, zs, Y, u, th, sec))

            for rho in (1000.0, 1025.0):
                _put(out, "michell_rw[%s,rho%g]" % (tag, rho),
                     R.michell_rw(xs, zs, Y, u, rho))
            _put(out, "michell_rw[%s,nt73]" % tag,
                 R.michell_rw(xs, zs, Y, u, n_theta=73))

            th2, sp = R.free_wave_spectrum(xs, zs, Y, u)
            _put(out, "free_wave_spectrum[%s].thetas" % tag, th2)
            _put(out, "free_wave_spectrum[%s].spectrum" % tag, sp)

        # The catamaran path is a DIFFERENT theta grid (the measured
        # separation rule), so it is not the monohull path with a factor on it.
        for fn in (0.28, R.FN_MICHELL_MAX):
            u = fn * math.sqrt(R.G * lwl)
            beam = 2.0 * float(np.max(Y))
            for ratio in _SEP_RATIOS:
                s = max(ratio * lwl, beam * 1.25)
                tag = "%s@fn%.3f,s%.4f" % (name, fn, s)
                _put(out, "michell_rw.cat[%s]" % tag,
                     R.michell_rw(xs, zs, Y, u, separation=s))
                th3, sp3 = R.free_wave_spectrum(xs, zs, Y, u, separation=s)
                _put(out, "free_wave_spectrum.cat[%s].spectrum" % tag, sp3)
            seps = np.array([max(r * lwl, beam * 1.25) for r in _SEP_RATIOS])
            _put(out, "michell_rw_separation_sweep[%s@fn%.3f]" % (name, fn),
                 R.michell_rw_separation_sweep(xs, zs, Y, u, seps))

    # -- the speed floor and every refusal on the michell path --------------
    xs, zs, Y, lwl = (*_wigley_grid(41, 14), 10.0)
    _put(out, "michell_rw.speed_floor", R.michell_rw(xs, zs, Y, 0.05))
    _put(out, "michell_rw.speed_floor_cat",
         R.michell_rw(xs, zs, Y, 0.05, separation=3.0))
    thf, spf = R.free_wave_spectrum(xs, zs, Y, 0.04)
    _put(out, "free_wave_spectrum.speed_floor", spf)
    _put(out, "michell_rw_separation_sweep.speed_floor",
         R.michell_rw_separation_sweep(xs, zs, Y, 0.05, np.array([3.0, 9.0])))
    for bad in (0.0, -2.0, float("nan"), float("inf"), None, "3"):
        _raises(out, "separation_or_raise[%r]" % (bad,),
                R._separation_or_raise, Y, bad)
    _raises(out, "separation_or_raise.intersecting", R._separation_or_raise,
            Y, 0.5)
    _raises(out, "michell_rw.coarse_theta", R.michell_rw, xs, zs, Y, 2.5,
            n_theta=220, separation=3.0)
    _raises(out, "sweep.empty", R.michell_rw_separation_sweep, xs, zs, Y, 2.5,
            np.array([]))
    _raises(out, "sweep.2d", R.michell_rw_separation_sweep, xs, zs, Y, 2.5,
            np.zeros((2, 2)))
    _raises(out, "sweep.coarse", R.michell_rw_separation_sweep, xs, zs, Y, 2.5,
            np.array([3.0, 40.0]), n_theta=880)

    # -- total_resistance: the production path, both vessel topologies ------
    ns, nz = R.PRODUCTION_GRID["n_stations"], R.PRODUCTION_GRID["nz"]
    for name, params in _reference_hulls():
        hull = Hull(params, n_stations=ns)
        lwl_design = float(hull.x[-1])
        wetted, cb = 18.4, 0.512
        beam_wl, draft = 2.85, 0.3737
        for fn in (0.12, 0.28, R.FN_MICHELL_MAX, 0.52):
            u = fn * math.sqrt(R.G * lwl_design)
            # `lwl_eff` variants: absent (design length), shortened by rocker
            # and trim, and lengthened — C-08's whole point.
            for le_tag, le in (("none", None), ("0.94", 0.94 * lwl_design),
                               ("1.03", 1.03 * lwl_design)):
                for rho in (1000.0, 1025.0):
                    for sep in (None, 4.2):
                        rr = R.total_resistance(
                            hull, u, wetted, cb, rho=rho, wl=0.0, nz=nz,
                            n_stations=ns, beam_wl=beam_wl, draft=draft,
                            separation=sep, lwl_eff=le)
                        k = ("total_resistance[%s,fn%.3f,le%s,rho%g,sep%s]"
                             % (name, fn, le_tag, rho, sep))
                        for f in ("speed", "fn", "rw", "rf", "total", "cw",
                                  "cf", "uncertainty"):
                            _put(out, "%s.%s" % (k, f), getattr(rr, f))
                        _put(out, k + ".valid", rr.valid)
                        _put(out, k + ".regime", rr.regime)
                        _put(out, k + ".n_hulls", rr.n_hulls)
                        _put(out, k + ".separation_m", rr.separation_m)
                        _put(out, k + ".grid", rr.grid)
                        _put(out, k + ".notes", rr.method_notes)
                        _put(out, k + ".form.k", rr.form.k)
                        _put(out, k + ".form.k_raw", rr.form.k_raw)
                        _put(out, k + ".form.sigma_k", rr.form.sigma_k)
                        _put(out, k + ".form.clamped", rr.form.clamped)
                        _put(out, k + ".flow.fn", rr.flow.fn)
                        _put(out, k + ".flow.re", rr.flow.re)
                        _put(out, k + ".flow.valid", rr.flow.valid)
        # The non-production grid path (`hull.n_stations != ns`) and the
        # design-beam/draft fallback, which is a different code branch.
        small = Hull(params, n_stations=41)
        rr = R.total_resistance(small, 2.5, wetted, cb)
        k = "total_resistance.fallback[%s]" % name
        for f in ("rw", "rf", "total", "cw", "cf", "uncertainty", "fn"):
            _put(out, "%s.%s" % (k, f), getattr(rr, f))
        _put(out, k + ".form.k", rr.form.k)

    return out


# ---------------------------------------------------------------------------
# THE EQUALITY TESTS
# ---------------------------------------------------------------------------

def test_golden_covers_every_public_name_in_the_module():
    """A golden that silently stops covering a function is not a golden.

    Enumerated from the module rather than from a hand-list, so a NEW public
    function fails this test on the day it is added instead of on the day
    someone optimises it.
    """
    public = {n for n in dir(R)
              if not n.startswith("_") and callable(getattr(R, n))
              and getattr(getattr(R, n), "__module__", "") == R.__name__}
    # Dataclasses are covered through the functions that return them.
    public -= {"FlowRegime", "FormFactor", "ResistanceResult"}
    keys = "\n".join(GOLDEN)
    missing = sorted(n for n in public if n not in keys)
    assert not missing, "golden does not exercise: %s" % missing
    # The two private hot-path helpers this optimisation actually rewrote.
    for n in ("_theta_grid", "_free_wave_vals", "_separation_or_raise"):
        assert n.lstrip("_") in keys or n in keys, n


def test_numpy_scalar_square_is_libm_pow_not_the_product():
    """Trap 1, MEASURED, because the fix depends on it being true.

    If a future numpy makes `np.float64 ** 2` the correctly-rounded product,
    `_free_wave_vals`' `np.float_power(..., 2.0)` becomes the wrong choice and
    the golden will go red. This test says WHY before that happens.
    """
    v = np.random.default_rng(11).uniform(0.5, 5000.0, 200_000)
    scalar = np.array([np.float64(x) ** 2 for x in v])
    bits = lambda a: np.asarray(a, dtype=np.float64).view(np.uint64)  # noqa: E731

    # float_power is the ONLY array expression that reproduces the scalar path.
    assert np.array_equal(bits(scalar), bits(np.float_power(v, 2.0)))
    # ... and every obvious alternative genuinely fails, in both directions.
    for alt in (v ** 2, v ** 2.0, np.square(v), v * v,
                np.power(v, 2), np.power(v, 2.0)):
        assert not np.array_equal(bits(scalar), bits(alt))
    # Exponent 3 is the opposite case: no numpy fast path, so both are pow.
    cube = np.array([np.float64(x) ** 3 for x in v])
    assert np.array_equal(bits(cube), bits(v ** 3))
    assert np.array_equal(bits(cube), bits(np.float_power(v, 3.0)))


def test_numpy_trapezoid_batches_bit_exactly():
    """Trap 3, MEASURED: promoting the reduction axis preserves the order.

    `np.trapezoid` ends in `.sum(axis)`, which is PAIRWISE — so this is a real
    question and not a formality. It is the licence for the whole rewrite: a
    per-slice call and one batched call over a new leading axis must agree bit
    for bit, and chunking that leading axis must change nothing.
    """
    rng = np.random.default_rng(3)
    bits = lambda a: np.asarray(a, dtype=np.float64).view(np.uint64)  # noqa: E731

    for nx in (241, 44, 97, 25, 481):
        x = np.sort(rng.uniform(0.0, 10.0, nx))
        A = rng.normal(size=(220, nx))
        loop = np.array([np.trapezoid(A[i], x) for i in range(A.shape[0])])
        assert np.array_equal(bits(loop), bits(np.trapezoid(A, x, axis=-1)))

    for nx, nz in ((241, 44), (97, 25), (41, 14)):
        z = np.sort(rng.uniform(-3.0, 0.0, nz))
        B = rng.normal(size=(53, nx, nz))
        loop = np.stack([np.trapezoid(B[i], z, axis=1) for i in range(53)])
        full = np.trapezoid(B, z, axis=2)
        assert np.array_equal(bits(loop), bits(full))
        chunked = np.concatenate(
            [np.trapezoid(B[i:i + 16], z, axis=2) for i in range(0, 53, 16)])
        assert np.array_equal(bits(full), bits(chunked))


#: The architecture this golden was RECORDED on. A bit-for-bit baseline is
#: a claim about one machine's floating point, and this file says which.
GOLDEN_ARCH = "x86_64"


def test_resistance_is_bit_identical_to_the_golden():
    """THE BAR. Every number this module produces, to the last bit.

    Not `allclose`. Not 1e-15. `float.hex()` and a SHA-256 over the raw IEEE
    bytes, because `michell_rw` feeds pinned figures across this repository and
    a one-ulp move is a change, not a rounding error.

    AND THE BAR IS PLATFORM-LOCAL, which is not a weakness but has to be
    SAID. MEASURED 2026-08-20: the geometry kernel's sibling equality test
    passed on fortress001 (Intel N100, x86-64) and failed on the Mac
    (Apple M5 Pro, arm64) at 62 of 514 elements, worst |diff| 1.110e-16 —
    exactly one ulp. Same arithmetic, different SIMD and FMA schedule;
    IEEE-754 permits the rounding. The h011/h012 investigation found the
    same fact from the other end, measuring `stl_sha256` non-portable
    between these two machines.

    So a mismatch HERE means one of two very different things, and the
    failure must say which: on x86-64 it is a REGRESSION and the number
    moved; on another architecture it is EXPECTED and the golden simply
    was not recorded there. Reporting the second as the first would send
    someone hunting a defect that does not exist.
    """
    import platform

    got = golden_payload()
    assert set(got) == set(GOLDEN), (
        "golden key set moved: +%s -%s"
        % (sorted(set(got) - set(GOLDEN))[:8], sorted(set(GOLDEN) - set(got))[:8]))
    bad = [(k, GOLDEN[k], got[k]) for k in sorted(GOLDEN) if GOLDEN[k] != got[k]]
    here = platform.machine()
    where = ("REGRESSION: this is %s, the architecture the golden was "
             "recorded on, so the numbers genuinely moved." % GOLDEN_ARCH
             if here == GOLDEN_ARCH else
             "PLATFORM: this is %r and the golden was recorded on %r. A "
             "one-ulp spread between architectures is IEEE-legal and "
             "MEASURED between these two machines; re-record the golden "
             "here before reading this as a code change." % (here, GOLDEN_ARCH))
    assert not bad, "%d of %d keys moved. %s\n%s" % (
        len(bad), len(GOLDEN), where,
        "\n".join("  %s: golden %s -> got %s" % b for b in bad[:20]))


def test_free_wave_vals_matches_the_reference_loop_it_replaced():
    """The batched integrand against the ORIGINAL per-theta loop, verbatim.

    The golden pins the current answer; this pins the current answer to the
    code that used to produce it, transcribed here exactly as it stood — the
    only way to say "the rewrite is the same computation" rather than "the
    rewrite agrees with itself".
    """
    def reference(xs, zs, Y, speed, thetas, sec):
        k0 = R.G / speed ** 2
        dydx = np.gradient(Y, xs, axis=0)
        vals = np.empty(len(thetas))
        for i, (th, sc) in enumerate(zip(thetas, sec)):
            depth = np.exp(np.minimum(k0 * sc ** 2 * zs, 0.0))[None, :]
            phase = k0 * sc * xs
            gz = (dydx * depth)
            fx = np.trapezoid(gz, zs, axis=1)
            re = np.trapezoid(fx * np.cos(phase), xs)
            im = np.trapezoid(fx * np.sin(phase), xs)
            vals[i] = (re ** 2 + im ** 2) * sc ** 3
        return vals

    for name, xs, zs, Y, lwl in _grids():
        for fn, n_theta in ((0.12, 220), (0.28, 220), (0.45, 441), (0.38, 73)):
            u = fn * math.sqrt(R.G * lwl)
            th, sec = R._theta_grid(n_theta)
            want = reference(xs, zs, Y, u, th, sec)
            got = R._free_wave_vals(xs, zs, Y, u, th, sec)
            assert np.array_equal(want.view(np.uint64), got.view(np.uint64)), (
                "%s fn=%.3f n_theta=%d: %d of %d values moved"
                % (name, fn, n_theta,
                   int(np.count_nonzero(want.view(np.uint64)
                                        != got.view(np.uint64))), want.size))


def test_free_wave_vals_is_chunk_size_independent():
    """The chunking is a MEMORY bound, not a numerical parameter.

    `_FREE_WAVE_CHUNK_BYTES` exists so a 17 600-node catamaran sweep does not
    materialise a 1.5 GB tensor. If the answer depended on it, it would be a
    quadrature knob wearing a memory knob's name — so it is measured not to be.
    """
    xs, zs, Y = _wigley_grid(241, 44)
    th, sec = R._theta_grid(220)
    base = R._free_wave_vals(xs, zs, Y, 2.5, th, sec)
    saved = R._FREE_WAVE_CHUNK_BYTES
    try:
        for nbytes in (1, 8_192, 262_144, 1 << 30):
            R._FREE_WAVE_CHUNK_BYTES = nbytes
            got = R._free_wave_vals(xs, zs, Y, 2.5, th, sec)
            assert np.array_equal(base.view(np.uint64), got.view(np.uint64)), (
                "chunk bytes %d changed the integrand" % nbytes)
    finally:
        R._FREE_WAVE_CHUNK_BYTES = saved


def test_the_physics_knobs_are_where_they_were():
    """Speed only. A resolution or a constant that moved is not an optimisation.

    Spelled out separately from the value golden so that "the numbers moved"
    and "someone cheapened the quadrature" are two different red tests with two
    different messages.
    """
    assert R.PRODUCTION_GRID == {"n_stations": 241, "nz": 44}
    assert R.CONVERGED_GRID == {"n_stations": 481, "nz": 88}
    assert R.GRID_CONVERGED_TO == 0.005
    assert R.N_THETA_MONOHULL == 220
    assert R.N_THETA_PER_HULL_LENGTH_OF_SEPARATION == 880
    assert R.FN_MICHELL_MAX == 0.45
    assert R.FORM_FACTOR_BAND == (0.0, 0.45)
    assert R.WATANABE_L_OVER_B_BAND == (6.0, 8.0)
    assert R.FORM_FACTOR_SIGMA_DECLARED == 0.05
    assert R.CATAMARAN_INTERFERENCE_AT_INFINITY == 2.0
    assert R.CATAMARAN_THETA_QUADRATURE_ERROR == 0.00061
    assert R.CATAMARAN_ASYMPTOTIC_RESIDUAL == 0.0049
    # The theta grid is a shape, not a scalar: pin the substitution itself.
    th, sec = R._theta_grid(220)
    s = np.linspace(1e-4, 1.0, 220) ** 0.7
    assert np.array_equal(th.view(np.uint64),
                          (0.5 * math.pi * s * 0.998).view(np.uint64))
    assert np.array_equal(sec.view(np.uint64),
                          (1.0 / np.cos(th)).view(np.uint64))


@pytest.mark.parametrize("nx,nz,n_theta,bar", [
    (41, 14, 220, 3.0),      # MEASURED 9.6x — wrapper-overhead-bound
    (97, 25, 880, 2.0),      # MEASURED 4.4x — mixed
    (241, 44, 220, 1.0),     # MEASURED 2.1x — bandwidth-bound, REPORTED only
])
def test_michell_rw_is_faster_than_the_loop_it_replaced(nx, nz, n_theta, bar):
    """The reason the rewrite exists, MEASURED rather than asserted.

    THE BARS ARE NOT UNIFORM AND THAT IS THE POINT. Two different things were
    wrong with the per-theta loop and they scale differently:

      * `np.trapezoid` WRAPPER OVERHEAD — ~60 us of Python per call, 660 calls
        per `michell_rw`. On a small grid that is nearly the whole cost, so the
        batch is 9.6x and stays 9.6x whatever else the machine is doing. This
        is the regression detector: if the loop comes back, this row fails by a
        mile on any hardware.
      * MEMORY BANDWIDTH — on the 241x44 production grid the integrand tensor
        is real work, the batch wins 2.1x on a quiet machine, and on a CONTENDED
        one it has been MEASURED as low as 1.2x, because the batch's larger
        working set is the part a competing process evicts. Pinning 2x there
        would be pinning the load average, so that row asserts only that the
        batch is faster at all and REPORTS the ratio.

    MEASURED (best-of-9, quiet, this machine, ms per call, reference -> batch):
        41x14  n_theta 220   14.67 -> 1.53   (9.6x)
        97x25  n_theta 880   86.63 -> 19.81  (4.4x)
       241x44  n_theta 220   27.00 -> 12.95  (2.1x)
       481x88  n_theta 220   90.93 -> 58.19  (1.6x)
    """
    import time

    def reference(xs, zs, Y, speed, thetas, sec):
        k0 = R.G / speed ** 2
        dydx = np.gradient(Y, xs, axis=0)
        vals = np.empty(len(thetas))
        for i, (th, sc) in enumerate(zip(thetas, sec)):
            depth = np.exp(np.minimum(k0 * sc ** 2 * zs, 0.0))[None, :]
            phase = k0 * sc * xs
            fx = np.trapezoid(dydx * depth, zs, axis=1)
            vals[i] = (np.trapezoid(fx * np.cos(phase), xs) ** 2
                       + np.trapezoid(fx * np.sin(phase), xs) ** 2) * sc ** 3
        return vals

    xs, zs, Y = _wigley_grid(nx, nz)
    th, sec = R._theta_grid(n_theta)
    for fn in (reference, R._free_wave_vals):     # warm both
        fn(xs, zs, Y, 2.5, th, sec)

    def best(fn, reps=5):
        out = float("inf")
        for _ in range(reps):
            t = time.perf_counter()
            fn(xs, zs, Y, 2.5, th, sec)
            out = min(out, time.perf_counter() - t)
        return out

    # Interleaved, because a machine that gets busy between two timings turns a
    # speed measurement into a load measurement.
    slow = min(best(reference), best(reference))
    fast = min(best(R._free_wave_vals), best(R._free_wave_vals))
    assert fast * bar < slow, (
        "%dx%d n_theta=%d: batched integrand %.2f ms vs per-theta loop %.2f ms "
        "(%.2fx, bar %.1fx) — the wrapper overhead is back"
        % (nx, nz, n_theta, fast * 1e3, slow * 1e3, slow / fast, bar))


@pytest.mark.parametrize("nx,nz,n_theta", [
    (2, 2, 1),        # the smallest grid `np.gradient` will accept at all
    (3, 2, 5),        # one z interval — the trapezoid has a single term
    (241, 2, 220),    # production stations, degenerate depth
    (2, 44, 220),     # two stations, production depth
    (41, 14, 1),      # a single theta node
    (481, 88, 3),     # the CONVERGED grid, fewer nodes than one chunk holds
])
def test_free_wave_vals_matches_the_reference_on_degenerate_grids(nx, nz, n_theta):
    """The shapes where chunking, slicing and empty axes can disagree.

    `step_z` is a byte budget divided by `nx * nz`, so a 481x88 grid gets ONE
    theta per chunk and a 41x14 grid gets 111 — the two ends of the chunk
    arithmetic — while `nz = 2` leaves the z-trapezoid a single term and
    `n_theta = 1` leaves the outer loop a single pass. All of them are
    off-by-one country, so all of them are measured against the reference.
    """
    xs, zs, Y = _wigley_grid(nx, nz)
    th, sec = R._theta_grid(n_theta)
    want = R._free_wave_vals_per_theta(xs, zs, Y, 2.5, th, sec)
    got = R._free_wave_vals(xs, zs, Y, 2.5, th, sec)
    assert np.array_equal(want.view(np.uint64), got.view(np.uint64))


def test_free_wave_vals_falls_back_rather_than_answering_differently():
    """Narrower inputs go to the reference instead of being promoted silently.

    The batch accumulates into float64 buffers. That is what the per-theta form
    does too — UNLESS every input is float32, in which case the reference stays
    in float32 and the batch would not. Nothing in this module produces such a
    call; the guard exists so that "faster" can never quietly mean "different",
    which is the whole failure mode this file was written to make impossible.
    """
    xs, zs, Y = _wigley_grid(41, 14)
    th, sec = R._theta_grid(37)
    f32 = [np.asarray(v, dtype=np.float32) for v in (xs, zs, Y, sec)]
    want = R._free_wave_vals_per_theta(f32[0], f32[1], f32[2], 2.5, th, f32[3])
    got = R._free_wave_vals(f32[0], f32[1], f32[2], 2.5, th, f32[3])
    assert np.array_equal(np.asarray(want, dtype=np.float64).view(np.uint64),
                          np.asarray(got, dtype=np.float64).view(np.uint64))
    # ... and the float64 call it is guarding does NOT take the fallback.
    assert not np.array_equal(
        np.asarray(got, dtype=np.float64).view(np.uint64),
        R._free_wave_vals(xs, zs, Y, 2.5, th, sec).view(np.uint64))


